fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    val k = sc.nextLong()
    val result = findKthPermutation(n, k)
    println(result.joinToString(" "))
}

fun findKthPermutation(n: Int, k: Long): IntArray {
    val list = generateFixedPermutations(n)
    return list[k - 1]
}

fun generateFixedPermutations(n: Int): List<IntArray> {
    val result = mutableListOf<IntArray>()
    val perm = IntArray(n) { it + 1 }
    generate(perm, 0, result)
    result.sortWith(compareBy { it.toList() })
    return result
}

fun generate(perm: IntArray, pos: Int, result: MutableList<IntArray>) {
    if (pos == perm.size) {
        if (isFixed(perm)) {
            result.add(perm.clone())
        }
        return
    }
    for (i in pos until perm.size) {
        swap(perm, pos, i)
        generate(perm, pos + 1, result)
        swap(perm, pos, i)
    }
}

fun swap(arr: IntArray, i: Int, j: Int) {
    val temp = arr[i]
    arr[i] = arr[j]
    arr[j] = temp
}

fun isFixed(perm: IntArray): Boolean {
    val n = perm.size
    val visited = BooleanArray(n)
    val cycles = mutableListOf<List<Int>>()
    for (i in 0 until n) {
        if (!visited[i]) {
            val cycle = mutableListOf<Int>()
            var j = i
            while (!visited[j]) {
                visited[j] = true
                cycle.add(j + 1)
                j = perm[j] - 1
            }
            cycles.add(cycle)
        }
    }
    // Normalize cycles: each cycle starts with max element, then sorted by first element
    val normalized = cycles.map { cycle ->
        val maxIdx = cycle.indexOf(Collections.max(cycle))
        val rotated = cycle.subList(maxIdx, cycle.size) + cycle.subList(0, maxIdx)
        rotated
    }.sortedBy { it[0] }
    // Build the standard representation as a permutation
    val standard = IntArray(n)
    for (cycle in normalized) {
        for (i in 0 until cycle.size) {
            val from = cycle[i]
            val to = cycle[(i + 1) % cycle.size]
            standard[from - 1] = to
        }
    }
    return perm.toList() == standard.toList()
}
