fun findKthFixedPermutation(n: Int, k: Long, perm: IntArray): IntArray {
    val fixedPoints = mutableListOf<Int>()
    for (i in 1..n) {
        if (perm[i] == i) fixedPoints.add(i)
    }
    if (fixedPoints.size == n) {
        return perm.clone()
    }
    val first = fixedPoints[0]
    val nextPerm = perm.clone()
    nextPerm[first] = first + 1
    nextPerm[first + 1] = first
    val count = countFixed(n, perm)
    if (k <= count) {
        return findKthFixedPermutation(n, k, perm)
    } else {
        return findKthFixedPermutation(n, k - count, nextPerm)
    }
}

fun countFixed(n: Int, perm: IntArray): Long {
    var count = 1L
    var i = 1
    while (i <= n) {
        if (perm[i] == i) {
            i++
            continue
        }
        var cycleLen = 0
        var j = i
        while (perm[j] != i) {
            j = perm[j]
            cycleLen++
        }
        cycleLen++
        if (cycleLen == 1) {
            count *= 1
        } else {
            count *= factorial(cycleLen - 1)
        }
        i += cycleLen
    }
    return count
}

fun factorial(n: Int): Long {
    var res = 1L
    for i in 1..n {
        res *= i
    }
    return res
}
