### Approach
1. **Understanding Fixed Permutations**: A permutation is fixed if its standard cyclic representation, when converted back to a permutation, results in the same permutation. This means each cycle in the permutation must be in decreasing order starting from the maximum element.
2. **Cycle Decomposition**: Each permutation can be decomposed into cycles. For a permutation to be fixed, each cycle must start with its maximum element and the elements within the cycle must be in decreasing order.
3. **Lexicographic Order**: The permutations are listed in lexicographic order. We need to generate the k-th permutation in this order.

### Solution Code
```kotlin
import java.util.*

fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    var k = sc.nextLong()

    val perm = IntArray(n + 1) // 1-based
    val used = BooleanArray(n + 1)
    val cycles = mutableListOf<List<Int>>()

    fun generate(current: Int) {
        if (current > n) {
            if (k == 1L) {
                // Build the permutation from cycles
                val p = IntArray(n + 1)
                for (cycle in cycles) {
                    for (i in 0 until cycle.size) {
                        val from = cycle[i]
                        val to = cycle[(i + 1) % cycle.size]
                        p[from] = to
                    }
                }
                for (i in 1..n) {
                    print("${p[i]} ")
                }
                println()
                System.exit(0)
            }
            k--
            return
        }

        // Try all possible cycles starting at 'current' (since current is the next unused)
        // The cycle must start with the maximum element, which is 'current' here
        // So the cycle is [current, ...] in decreasing order
        // The elements in the cycle must be a subset of unused elements including current
        // and all elements in the cycle must be <= current (since current is the max)
        // So we can choose any subset of unused elements <= current that includes current
        // and form a cycle with them in decreasing order

        val candidates = (1..current).filter { !used[it] }
        val m = candidates.size
        // Iterate over all non-empty subsets of candidates that include 'current'
        // Each subset forms a cycle starting with current, followed by the rest in decreasing order
        for (mask in 1..(1 shl m) - 1) {
            if ((mask and (1 shl (m - 1))) == 0) continue // must include current (last in candidates)
            val subset = mutableListOf<Int>()
            for (i in 0 until m) {
                if (mask and (1 shl i) != 0) {
                    subset.add(candidates[i])
                }
            }
            // The cycle is subset sorted in decreasing order, starting with current
            subset.sortDescending()
            if (subset[0] != current) continue // current must be the max
            // Mark these as used
            for (x in subset) used[x] = true
            cycles.add(subset)
            generate(current + 1)
            cycles.removeAt(cycles.size - 1)
            for (x in subset) used[x] = false
        }
    }

    generate(1)
}
