fun countCycles(n: Long, cycleLength: Long): BigInteger {
    if (cycleLength > n) return BigInteger.ZERO
    var result = BigInteger.ONE
    for (i in 0 until cycleLength - 1) {
        result = result.multiply(BigInteger.valueOf(n - i))
    }
    result = result.divide(BigInteger.valueOf(cycleLength))
    return result
}

fun buildCycle(n: Long, cycleLength: Long): List<Long> {
    val cycle = mutableListOf<Long>()
    var current = n
    for (i in 0 until cycleLength) {
        cycle.add(current)
        current--
    }
    return cycle
}
