fun findKthPermutation(n: Int, k: Long): IntArray {
    val fixedPoints = mutableListOf<Int>()
    val cycles = mutableListOf<MutableList<Int>>()
    var remaining = n
    var currentK = k - 1

    for (i in 1..n) {
        if (remaining == 0) break
        val cycleCount = countCycles(remaining)
        val fixedPointCount = countFixedPoints(remaining)
        val total = cycleCount + fixedPointCount
        if (currentK < cycleCount) {
            val cycle = generateCycle(remaining, currentK)
            cycles.add(cycle)
            remaining -= cycle.size
        } else {
            currentK -= cycleCount
            fixedPoints.add(i)
            remaining--
        }
    }

    val permutation = IntArray(n)
    for (i in 0 until n) {
        permutation[i] = i + 1
    }

    for (cycle in cycles) {
        for (i in cycle.indices) {
            val from = cycle[i] - 1
            val to = cycle[(i + 1) % cycle.size] - 1
            permutation[from] = to + 1
        }
    }

    return permutation
}

fun countCycles(n: Int): Long {
    if (n <= 1) return 0
    var result = 0L
    var factorial = 1L
    for (i in 1..n) {
        factorial *= i
    }
    for (i in 2..n) {
        result += factorial / i
    }
    return result
}

