fun generateCycle(n: Int, k: Long): MutableList<Int> {
    val cycle = mutableListOf<Int>()
    val elements = (1..n).toMutableList()
    var currentK = k
    var size = n
    while (size > 0) {
        val factorial = factorial(size - 1)
        val index = (currentK / factorial).toInt()
        currentK %= factorial
        cycle.add(elements.removeAt(index))
        size--
    }
    return cycle
}

fun factorial(n: Int): Long {
    var result = 1L
    for (i in 1..n) {
        result *= i
    }
    return result
